<template>
    <section class="history-panel">
        <header class="history-heading"><div><span class="eyebrow">REKAM JEJAK KUIS</span><h2>Riwayat Kuis</h2><p>Setiap percobaan tetap tersimpan. Buka detail untuk melihat versi soal dan jawaban yang dikerjakan.</p></div><button :disabled="loading" @click="load(1)">Perbarui</button></header>
        <div v-if="canFilterStudents" class="history-filters">
            <label>Cari peserta<input v-model="participantSearch" type="search" placeholder="Nama atau username peserta..." /></label>
            <label>Peserta<select v-model="selectedUsername" :disabled="loading"><option value="">Semua peserta</option><option v-for="participant in filteredParticipants" :key="participant.username" :value="participant.username">{{ participant.name }} ({{ participant.username }})</option><option v-if="selectedUsername && !participants.some(p => p.username === selectedUsername)" :value="selectedUsername">{{ selectedUsername }}</option></select></label>
            <button v-if="selectedUsername || participantSearch" :disabled="loading" @click="resetParticipants">Reset filter peserta</button>
            <p v-if="participantSearch && !filteredParticipants.length" role="status">Tidak ada peserta yang cocok dengan pencarian.</p>
        </div>
        <div v-if="batchId || selectedUsername" class="scope">{{ batchId ? `Riwayat batch #${batchId}` : 'Semua penugasan' }} <span v-if="selectedUsername">· {{ selectedParticipantName }}</span><Link href="/riwayat-belajar">Lihat semua riwayat kuis</Link></div>
        <p v-if="error" class="history-error" role="alert">{{ error }}</p>
        <div v-if="loading" class="history-loading" role="status">Memuat riwayat kuis…</div>
        <div v-else-if="!rows.length && !error" class="history-empty"><h3>Belum ada riwayat untuk pilihan ini</h3><p>Riwayat batch dicatat saat kuis dimulai dari kelas di Pelatihan Saya. Percobaan lama tanpa catatan batch tetap tersedia di semua riwayat.</p></div>
        <div v-else class="history-list"><article v-for="row in rows" :key="row.id" class="history-row">
            <div class="attempt-icon">{{ row.attempt_number }}</div><div class="history-info"><div class="history-tags"><span>{{ row.batch_name || 'Tanpa catatan batch' }}</span><span>{{ row.recorded_version ? `Versi ${row.recorded_version}` : 'Sebelum pencatatan versi' }}</span></div><h3>{{ row.title }}</h3><p>{{ row.name }} · {{ date(row.started_at) }}</p><small>{{ row.status === 'IN_PROGRESS' ? 'Sedang dikerjakan' : row.pending_review ? 'Menunggu penilaian esai' : `Dikumpulkan ${date(row.submitted_at)}` }}</small></div>
            <div class="history-score"><strong>{{ row.score_visible && row.score !== null ? Number(row.score).toLocaleString('id-ID') : '—' }}</strong><span>{{ !row.score_visible ? 'Belum dirilis' : row.pending_review ? 'Menunggu nilai' : 'Nilai / 100' }}</span></div><button :disabled="row.status === 'IN_PROGRESS' || detailLoading" @click="review(row.id)">{{ row.status === 'IN_PROGRESS' ? 'Belum selesai' : 'Lihat detail' }}</button>
        </article></div>
        <nav v-if="lastPage > 1" class="history-pages" aria-label="Halaman riwayat"><button :disabled="loading || page <= 1" @click="load(page - 1)">Sebelumnya</button><span>{{ page }} / {{ lastPage }}</span><button :disabled="loading || page >= lastPage" @click="load(page + 1)">Berikutnya</button></nav>
        <dialog ref="dialog" class="history-dialog" aria-labelledby="history-detail-title" @close="closeDetail"><header class="history-heading"><h2 id="history-detail-title">Detail percobaan</h2><button @click="dialog.close()" aria-label="Tutup riwayat">Tutup ✕</button></header>
            <p v-if="detailLoading" role="status">Memuat rekaman percobaan…</p><p v-if="detailError" class="history-error" role="alert">{{ detailError }}</p>
            <template v-if="detail"><div class="review-summary"><h3>{{ detail.title }}</h3><p>{{ detail.student }} · Percobaan {{ detail.attempt_number }} · {{ detail.recorded_version ? `Versi ${detail.recorded_version}` : 'Versi lama tidak tercatat' }}</p><strong v-if="detail.score !== undefined && detail.score !== null">Nilai {{ detail.score }} / 100</strong><p>{{ detail.history_notice }}</p></div>
                <p v-if="!detail.questions.length" class="scope">Rincian jawaban belum dirilis oleh trainer.</p>
                <article v-for="(question, index) in detail.questions" :key="question.id" class="review-question"><h4>{{ index + 1 }}. {{ question.question }}</h4><img v-if="question.image_url" :src="question.image_url" class="review-image" alt="Gambar soal yang dikerjakan" loading="lazy" />
                    <ul v-if="question.options.length"><li v-for="option in question.options" :key="option.id" :class="{ chosen: question.selected_options.includes(option.id), correct: option.is_correct === true }">{{ option.text }} <span v-if="question.selected_options.includes(option.id)">· Jawaban peserta</span><span v-if="option.is_correct === true"> · Kunci benar</span></li></ul><p v-if="question.type === 'essay'" class="essay">{{ question.essay || 'Tidak dijawab' }}</p><p v-if="question.points !== undefined">Poin: {{ question.points ?? 'Belum dinilai' }} / {{ question.weight }}</p><p v-if="question.feedback">Feedback: {{ question.feedback }}</p><details v-if="question.explanation"><summary>Pembahasan saat dikerjakan</summary><p class="essay">{{ question.explanation }}</p></details>
                </article><details v-if="detail.grade_history?.length" class="material-record"><summary>Riwayat penilaian esai</summary><p v-for="(grade, i) in detail.grade_history" :key="i">{{ date(grade.created_at) }} &middot; {{ grade.graded_by }} &middot; Poin {{ grade.previous_points ?? 'belum dinilai' }} &rarr; {{ grade.points }}<br />{{ grade.feedback }}</p></details><details v-if="detail.materials?.length" class="material-record"><summary>Rekaman materi saat percobaan ({{ detail.materials.length }})</summary><article v-for="material in detail.materials" :key="material.id"><h4>{{ material.title || 'Materi' }} · {{ material.type }}</h4><p class="essay">{{ plainText(material.content) }}</p><p v-if="material.lampiran">Lampiran: {{ material.lampiran }}</p></article><p>Rekaman ini mempertahankan teks dan referensi file. Isi layanan eksternal dapat berubah di luar LMS.</p></details>
            </template>
        </dialog>
    </section>
</template>

<script setup>
import { ref, computed, watch, onBeforeUnmount } from 'vue';
import { Link } from '@inertiajs/vue3';
import { apiInstance } from '@/utils/axios';
import { errorMessage } from '@/pages/quiz/errors.mjs';
const props = defineProps({ batchId: { default: null }, username: { default: '' } });
const selectedUsername = ref(props.username), participantSearch = ref(''), participants = ref([]), canFilterStudents = ref(false);
const filteredParticipants = computed(() => {
    const term = participantSearch.value.trim().toLocaleLowerCase('id');
    return participants.value.filter(p => p.username === selectedUsername.value || `${p.name} ${p.username}`.toLocaleLowerCase('id').includes(term));
});
const selectedParticipantName = computed(() => {
    const participant = participants.value.find(p => p.username === selectedUsername.value);
    return participant ? `${participant.name} (${participant.username})` : selectedUsername.value;
});
function resetParticipants() { participantSearch.value = ''; selectedUsername.value = ''; }
const rows = ref([]), page = ref(1), lastPage = ref(1), loading = ref(false), error = ref('');
const detail = ref(null), detailError = ref(''), detailLoading = ref(false), dialog = ref(null);
let listVersion = 0, detailVersion = 0;
const date = value => value ? new Date(value.includes('T') ? value : value.replace(' ', 'T')).toLocaleString('id-ID', { dateStyle: 'medium', timeStyle: 'short' }) : '—';
const failure = errorMessage;
const plainText = value => { if (!value) return ''; const doc = new DOMParser().parseFromString(String(value), 'text/html'); return doc.body.textContent || ''; };
async function load(target = 1) { const token = ++listVersion; loading.value = true; error.value = ''; rows.value = []; try { const { data } = await apiInstance.get('/api/learning-history', { params: { page: target, batch_id: props.batchId || undefined, username: selectedUsername.value || undefined } }); if (token !== listVersion) return; rows.value = data.data; page.value = data.current_page; lastPage.value = data.last_page; participants.value = data.participants ?? []; canFilterStudents.value = data.can_filter_students === true; } catch (e) { if (token === listVersion) error.value = failure(e); } finally { if (token === listVersion) loading.value = false; } }
async function review(id) { const token = ++detailVersion; detail.value = null; detailError.value = ''; detailLoading.value = true; dialog.value.showModal(); try { const { data } = await apiInstance.get(`/api/learning-history/${id}`); if (token === detailVersion) detail.value = data; } catch (e) { if (token === detailVersion) detailError.value = failure(e); } finally { if (token === detailVersion) detailLoading.value = false; } }
function closeDetail() { detailVersion++; detail.value = null; detailLoading.value = false; }
watch(() => props.username, value => { selectedUsername.value = value; participantSearch.value = ''; });
watch(() => [props.batchId, selectedUsername.value], () => load(1), { immediate: true });
onBeforeUnmount(() => { listVersion++; detailVersion++; });
</script>

<style scoped>
.history-filters{display:flex;align-items:end;flex-wrap:wrap;gap:14px;margin-top:22px;padding:16px;background:#faf8fd;border:1px solid #eee7f6;border-radius:14px}.history-filters label{display:grid;gap:7px;flex:1 1 220px;min-width:0;font-size:12px;font-weight:600;color:#665974}.history-filters input,.history-filters select{width:100%;min-width:0;padding:10px 12px;border:1px solid #ded6e9;border-radius:9px;background:white;font:inherit}.history-filters input:focus-visible,.history-filters select:focus-visible{outline:2px solid #9b6bd8;outline-offset:2px}.history-filters p{flex-basis:100%}
.history-panel{background:#fff;border:1px solid #e8e6ef;border-radius:22px;padding:26px;color:#20243b}.history-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.eyebrow{font-size:10px;letter-spacing:1.5px;font-weight:700;color:#7834de}h2{font-size:23px;font-weight:700}h3{font-weight:650;font-size:16px}h4{font-weight:600}p,small{color:#737888;font-size:13px;line-height:1.7}button{border:1px solid #ddd7e8;border-radius:10px;padding:9px 14px;font-size:12px;font-weight:600;color:#6530b0;background:white}button:hover{background:#f6f0ff;border-color:#b79adc}button:disabled{opacity:.45;cursor:not-allowed}.scope{padding:13px;background:#f6f2fd;border-radius:10px;margin:16px 0;font-size:13px}.scope a{color:#7437c5;margin-left:14px}.history-list{margin-top:20px}.history-row{display:flex;align-items:center;gap:18px;padding:20px 0;border-top:1px solid #f0edf5}.attempt-icon{width:42px;height:42px;border-radius:13px;background:#f1e8ff;color:#773aca;display:grid;place-items:center;font-weight:700;flex-shrink:0}.history-info{flex:1;min-width:0}.history-tags{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px}.history-tags span{font-size:10px;background:#f6f4f9;border-radius:5px;padding:3px 7px;color:#736a85}.history-score{text-align:center;min-width:76px}.history-score strong{display:block;font-size:24px;color:#6930b8}.history-score span{font-size:10px;color:#888}.history-pages{display:flex;justify-content:flex-end;align-items:center;gap:16px;padding-top:18px;font-size:13px}.history-loading,.history-empty{padding:40px;text-align:center;border:1px dashed #ded4ed;border-radius:15px;margin-top:20px}.history-error{color:#a92a42;background:#fff1f3;padding:12px;border-radius:10px;margin:12px 0}.history-dialog{width:min(850px,calc(100vw - 28px));max-height:90dvh;margin:auto;border:0;border-radius:22px;padding:26px;overflow:auto}.history-dialog::backdrop{background:#10082499;backdrop-filter:blur(3px)}.review-summary{margin:18px 0;background:#f6f2fc;border-radius:14px;padding:20px}.review-summary strong{color:#713bb8;font-size:22px}.review-question{padding:22px 0;border-top:1px solid #eee}.review-question li{padding:10px;margin:6px 0;border:1px solid #e7e6ec;border-radius:9px;font-size:13px}.review-question li.chosen{border-color:#9260d5;background:#f7f0ff}.review-question li.correct{border-color:#4b9e7c}.review-question li span{font-size:11px;color:#675680}.review-image{max-width:100%;max-height:300px;margin:12px 0}.essay{white-space:pre-wrap;overflow-wrap:anywhere}.material-record{background:#faf9fc;padding:18px;border-radius:13px}.material-record article{padding:14px 0;border-bottom:1px solid #eee}summary{cursor:pointer;font-weight:600;font-size:13px}details p{margin-top:10px}@media(max-width:640px){.history-panel{padding:16px}.history-row{flex-wrap:wrap;gap:12px}.history-info{min-width:calc(100% - 60px)}.history-score{text-align:left}.history-row>button{margin-left:auto}.history-dialog{padding:18px}.history-empty{padding:24px}h2{font-size:20px}}
</style>
